 print(\"LINKS\", [(a.get_text(\" \",strip=True),a.get(\"href\")) for a in p.find_all(\"a\") if a.get(\"href\") and (\"course\" in a.get_text(\" \",strip=True).lower() or \"program\" in a.get_text(\" \",strip=True).lower() or a.get(\"href\",\"\").lower().endswith((\".pdf\",\".doc\",\".docx\")))][:60])' \""'$task_tmp"'

